        children: "import { BusinessError } from '@kit.BasicServicesKit';\nimport { fileIo as fs } from '@kit.CoreFileKit';\nimport { common } from '@kit.AbilityKit';\n\nlet bufferSize: number;\nclass Options {\n  offset?: number;\n  length?: number;\n}\naudioRenderer.getBufferSize().then((data: number)=> {\n  console.info(`AudioFrameworkRenderLog: getBufferSize: SUCCESS ${data}`);\n  bufferSize = data;\n  console.info(`Buffer size: ${bufferSize}`);\n  // 请在组件内获取context，确保this.getUIContext().getHostContext()返回结果为UIAbilityContext。\n  let context = this.getUIContext().getHostContext() as common.UIAbilityContext;\n  let path = context.cacheDir;\n  // 此处仅作示例，实际使用时需要将文件替换为应用要播放的PCM文件。\n  let filePath = path + '/StarWars10s-2C-48000-4SW.pcm';\n  let file: fs.File = fs.openSync(filePath, fs.OpenMode.READ_ONLY);\n  fs.stat(filePath).then(async (stat: fs.Stat) => {\n    let buf = new ArrayBuffer(bufferSize);\n    let len = stat.size % bufferSize == 0 ? Math.floor(stat.size / bufferSize) : Math.floor(stat.size / bufferSize + 1);\n    for (let i = 0;i < len; i++) {\n      let options: Options = {\n        offset: i * bufferSize,\n        length: bufferSize\n      };\n      await fs.read(file.fd, buf, options);\n      await new Promise((resolve,reject)=>{\n        audioRenderer.write(buf,(err: BusinessError, writeSize: number)=>{\n          if(err){\n            reject(err)\n          }else{\n            resolve(writeSize)\n          }\n        })\n      })\n    }\n  });\n  }).catch((err: BusinessError) => {\n    console.error(`AudioFrameworkRenderLog: getBufferSize: ERROR: ${err}`);\n});\n"
